import React, { useState } from 'react';
import { register, login } from '../services/api';

export default function Login({ onLogin }){
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [mode, setMode] = useState('login');
  const [err, setErr] = useState(null);

  async function submit(e){
    e.preventDefault();
    try{
      const res = mode==='login' ? await login(username,password) : await register(username,password);
      if (res.msg === 'ok'){
        onLogin(res.user || {username});
      } else { setErr(JSON.stringify(res)); }
    }catch(e){
      const msg = String(e);
      // convert generic fetch failure into something user-friendly
      if (msg.includes('NetworkError')) {
        setErr('Unable to reach the server. Please make sure the backend is running and try again.');
      } else {
        setErr(msg);
      }
    }
  }

  return (
    <div style={{display:'flex',justifyContent:'center',alignItems:'center',minHeight:'100vh',background:'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'}}>
      <form onSubmit={submit} style={{width:360,padding:40,background:'white',borderRadius:16,boxShadow:'0 8px 32px rgba(0,0,0,0.2)'}}>
        <h2 style={{textAlign:'center',marginBottom:32,background:'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',WebkitBackgroundClip:'text',WebkitTextFillColor:'transparent',marginTop:0}}>{mode==='login' ? 'Login' : 'Register'}</h2>
        <div style={{marginBottom:16}}>
          <label style={{display:'block',marginBottom:8,fontWeight:500}}>Username</label>
          <input placeholder='Enter your username' value={username} onChange={e=>setUsername(e.target.value)} style={{margin:0}} />
        </div>
        <div style={{marginBottom:24}}>
          <label style={{display:'block',marginBottom:8,fontWeight:500}}>Password</label>
          <input placeholder='Enter your password' type='password' value={password} onChange={e=>setPassword(e.target.value)} style={{margin:0}} />
        </div>
        <button type='submit' style={{width:'100%',padding:14,marginBottom:16}}>{mode==='login' ? 'Login' : 'Register'}</button>
        <div style={{textAlign:'center'}}>
          <button type='button' onClick={()=>setMode(mode==='login'?'register':'login')} style={{background:'none',color:'#667eea',padding:0,textDecoration:'underline',fontWeight:500,boxShadow:'none'}}>{mode==='login' ? 'Create new account' : 'Already have account? Login'}</button>
        </div>
        {err && <div style={{color:'#e74c3c',marginTop:16,padding:12,backgroundColor:'#ffe6e6',borderRadius:8}}>{err}</div>}
      </form>
    </div>
  );
}
